11: *{box-sizing:border-box}[hidden]{display:none!important}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#142437;color:var(--cream);font-family:Nunito,system-ui,sans-serif;touch-action:none}button{font:inherit;color:inherit;cursor:pointer;border:0}
